import ast, pathlib, re
tr_words = re.compile(r"(bolum|disk|dosya|yok|hata|gecersiz|bulunam|yazil|okun|olust|bicim|secil|icin|degil|kucuk|buyuk|alan|sistem)", re.I)
for p in sorted(pathlib.Path("src/diskultimate/core").rglob("*.py")):
    src=p.read_text(encoding="utf-8")
    t=ast.parse(src)
    hits=0
    for node in ast.walk(t):
        if isinstance(node,(ast.Raise,)):
            for sub in ast.walk(node):
                if isinstance(sub,ast.Constant) and isinstance(sub.value,str) and tr_words.search(sub.value):
                    hits+=1
                if isinstance(sub,ast.JoinedStr):
                    txt="".join(v.value for v in sub.values if isinstance(v,ast.Constant))
                    if tr_words.search(txt): hits+=1
    if hits: print(f"{p}: raise-mesaji={hits}")
EOF

