QScrollBar::handle:horizontal {{ background: #b9c2cc; border-radius: 6px; min-width: 24px; }}
QScrollBar::add-line, QScrollBar::sub-line {{ width: 0; height: 0; }}
QToolTip {{
    background: #2f3b47; color: white; border: none; padding: 5px 8px; border-radius: 3px;
}}
"""


def apply_icon_theme() -> str:
    """Acik arayuz temasiyla uyumlu bir ikon seti secer.

    Masaustu koyu bir ikon temasi kullaniyorsa (orn. `breeze-dark`) ikonlar
    acik renkli olur ve uygulamanin acik zemininde gorunmez. Bu durumda ayni
    temanin acik surumune gecilir; o da yoksa Qt'nin gomulu ikonlarina dusulur.

    QApplication olusturulduktan SONRA cagrilmalidir. Secilen tema adini dondurur.
    """
    mevcut = QIcon.themeName()
    if not mevcut or not mevcut.lower().endswith("-dark"):
        return mevcut
    for aday in (mevcut[:-len("-dark")], "breeze", "Adwaita"):
        if not aday:
            continue
        QIcon.setThemeName(aday)
        if QIcon.hasThemeIcon("folder"):
            return aday
    QIcon.setThemeName("")      # Qt'nin gomulu ikon seti
    return ""


# --------------------------------------------------------------------------
# Tema uygulama (su an yalnizca "sistem")
# --------------------------------------------------------------------------
THEMES = {
    "system": "Sistem varsayilani",
    "diskultimate": "DiskUltimate (acik)",
}


def apply_theme(app, name: str = "system") -> str:
    """Uygulamaya tema uygular. Su an varsayilan 'system'dir.

    'system' : hicbir stil sayfasi uygulanmaz; masaustunun kendi gorunumu,
               paleti ve ikon temasi aynen kullanilir.
    'diskultimate' : proje icindeki acik tema (ileride Tema bolumunden secilir).
    """
    if name == "diskultimate":
        app.setStyleSheet(STYLESHEET)
        apply_icon_theme()
        return "diskultimate"
    app.setStyleSheet("")
    return "system"


def palette_color(widget, role: str = "text"):
    """Widget'in etkin paletinden renk dondurur.

    Sabit renk yazmak yerine bu kullanilir; boylece koyu/acik sistem temasinin
    ikisinde de metin okunabilir kalir.
    """
    from PyQt5.QtGui import QPalette

    roller = {
        "text": QPalette.WindowText,
        "dim": QPalette.PlaceholderText,
        "base": QPalette.Base,
        "window": QPalette.Window,
        "highlight": QPalette.Highlight,
        "highlight_text": QPalette.HighlightedText,
    }
    palet = widget.palette()
    renk = palet.color(roller.get(role, QPalette.WindowText))
    if role == "dim" and not renk.isValid():
        renk = palet.color(QPalette.WindowText)
        renk.setAlpha(150)
    return renk


def is_dark(widget) -> bool:
    """Etkin paletin koyu olup olmadigini soyler."""
    return palette_color(widget, "window").value() < 128


# --------------------------------------------------------------------------
# Isletim sistemi amblemleri
# --------------------------------------------------------------------------
# Marka logolarinin birebir kopyasi kullanilmaz; her biri stilize, taninabilir
# bir geometrik amblemdir. Amac diskleri hizlica ayirt edebilmek.
OS_COLORS = {
    "windows": "#0078D4",
    "linux": "#E8B71A",
    "macos": "#8E8E93",
}


def os_icon(os_name: str, size: int = 16) -> QIcon:
    """Isletim sistemi amblemi dondurur ('windows' | 'linux' | 'macos')."""
    pix = QPixmap(size, size)
    pix.fill(Qt.transparent)
    p = QPainter(pix)
    p.setRenderHint(QPainter.Antialiasing, True)
    try:
        if os_name == "windows":
            _draw_windows(p, size)
        elif os_name == "linux":
            _draw_linux(p, size)
        elif os_name == "macos":
            _draw_macos(p, size)
    finally:
        p.end()
    return QIcon(pix)


def _draw_windows(p: QPainter, size: int) -> None:
    """Dort kareli pencere amblemi."""
    renk = QColor(OS_COLORS["windows"])
    gap = max(1, size // 12)
    kenar = (size - gap * 3) // 2
    upper = gap
    for sutun in range(2):
        for satir in range(2):
            x = gap + sutun * (kenar + gap)
            y = upper + satir * (kenar + gap)
            p.fillRect(x, y, kenar, kenar, renk)


def _draw_linux(p: QPainter, size: int) -> None:
    """Stilize penguen: koyu govde, acik karin, sari gaga."""
    govde = QColor("#22252A")
    karin = QColor("#F2F2F2")
    gaga = QColor(OS_COLORS["linux"])
    kenar = size / 16.0

    p.setPen(Qt.NoPen)
    p.setBrush(govde)
    p.drawEllipse(QRectF(3 * kenar, 1.5 * kenar, 10 * kenar, 13 * kenar))
    p.setBrush(karin)
    p.drawEllipse(QRectF(5 * kenar, 6 * kenar, 6 * kenar, 8 * kenar))
    p.setBrush(gaga)
    gaga_sekli = QPolygonF([
        QPointF(6.5 * kenar, 5.5 * kenar),
        QPointF(9.5 * kenar, 5.5 * kenar),
        QPointF(8.0 * kenar, 7.5 * kenar),
    ])
    p.drawPolygon(gaga_sekli)
    # ayaklar
    p.drawEllipse(QRectF(3.5 * kenar, 13 * kenar, 4 * kenar, 2 * kenar))
    p.drawEllipse(QRectF(8.5 * kenar, 13 * kenar, 4 * kenar, 2 * kenar))
    # gozler
    p.setBrush(QColor("#FFFFFF"))
    p.drawEllipse(QRectF(5.6 * kenar, 3.2 * kenar, 2.0 * kenar, 2.6 * kenar))
    p.drawEllipse(QRectF(8.4 * kenar, 3.2 * kenar, 2.0 * kenar, 2.6 * kenar))
    p.setBrush(govde)
    p.drawEllipse(QRectF(6.2 * kenar, 3.9 * kenar, 1.0 * kenar, 1.4 * kenar))
    p.drawEllipse(QRectF(9.0 * kenar, 3.9 * kenar, 1.0 * kenar, 1.4 * kenar))


def _draw_macos(p: QPainter, size: int) -> None:
    """Yuvarlak kose amblem (marka logosu kullanilmaz)."""
    renk = QColor(OS_COLORS["macos"])
    kenar = size / 16.0
    p.setPen(Qt.NoPen)
    p.setBrush(renk)
    p.drawRoundedRect(QRectF(2 * kenar, 2 * kenar, 12 * kenar, 12 * kenar),
                      3 * kenar, 3 * kenar)
    p.setBrush(QColor("#FFFFFF"))
    p.drawEllipse(QRectF(6 * kenar, 5 * kenar, 4 * kenar, 4 * kenar))
    p.drawRoundedRect(QRectF(5 * kenar, 9.5 * kenar, 6 * kenar, 1.6 * kenar),
                      0.8 * kenar, 0.8 * kenar)


# --------------------------------------------------------------------------
# Ortak arayuz yardimcilari
# --------------------------------------------------------------------------
# `standard_icon()` kaldirildi: sistem `QStyle` ikonlari platforma gore
# bambaska goruntuluyordu ve aradigimiz islemlerin cogunun karsiligi yoktu.
# Butun ikonlar artik `ui/icons.py` icinde cizilir ve uc platformda da
# **birebir ayni** cikar (olculdu: ayni sha256, ADR 0025).

toolUseResult.stdout:
"""Butun disklerin tek ekranda gorunumu (Acronis / EaseUS duzeni).

`DiskMapWidget` **tek** bir acik diski cizer. Bu widget ise sistemdeki butun
diskleri alt alta, her birinin bolumleriyle birlikte gosterir — hicbir diski
acmadan. Kullanici "once ac, sonra bak" adimlarini yapmak zorunda kalmaz.

Veri, arka planda salt okunur yapilan bolum yoklamasindan gelir
(`DiskSession.survey_disk`, ADR 0026); bu widget hicbir aygita dokunmaz.
"""
from __future__ import annotations

from typing import Dict, List, Optional, Tuple

from PyQt5.QtCore import QRect, Qt, pyqtSignal
from PyQt5.QtGui import QColor, QFont, QPainter, QPen
from PyQt5.QtWidgets import QSizePolicy, QWidget

from ...core.ptable import human_size
from ..theme import FREE_COLOR, fs_color, palette_color

ROW_HEIGHT = 72
ROW_GAP = 8
LABEL_WIDTH = 132
MIN_BLOCK = 36
MARGIN = 8


class DiskOverviewWidget(QWidget):
    """Disk basina bir satir: solda kimlik kutusu, sagda bolum seridi."""

    diskSelected = pyqtSignal(str)                  # aygit yolu
    partitionSelected = pyqtSignal(str, int)        # aygit yolu, bolum numarasi
    partitionActivated = pyqtSignal(str, int)       # cift tiklama

    def __init__(self, parent=None):
        super().__init__(parent)
        self.setMouseTracking(True)
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Minimum)
        self._disks: List[object] = []
        self._surveys: Dict[str, object] = {}
        self._blocks: List[Tuple[QRect, str, int]] = []   # (alan, yol, index)
        self._rows: List[Tuple[QRect, str]] = []          # (alan, yol)
        self._hover: Optional[Tuple[str, int]] = None
        self._selected: Optional[Tuple[str, int]] = None

    # -- veri --------------------------------------------------------------
    def set_disks(self, disks, surveys) -> None:
        self._disks = list(disks or [])
        self._surveys = dict(surveys or {})
        self.setMinimumHeight(
            max(ROW_HEIGHT + 2 * MARGIN,
                len(self._disks) * (ROW_HEIGHT + ROW_GAP) + 2 * MARGIN))
        self.updateGeometry()
        self.update()

    def clear(self) -> None:
        self.set_disks([], {})

    # -- yerlesim ----------------------------------------------------------
    def _layout(self) -> None:
        self._blocks = []
        self._rows = []
        y = MARGIN
        strip_x = MARGIN + LABEL_WIDTH + 8
        strip_w = max(80, self.width() - strip_x - MARGIN)
        for info in self._disks:
            self._rows.append((QRect(MARGIN, y, LABEL_WIDTH, ROW_HEIGHT),
                               info.path))
            survey = self._surveys.get(info.path)
            parts = list(getattr(survey, "partitions", []) or [])
            total = max(1, info.size)
            if parts:
                # Oransal genislik + en kucuk genislik telafisi: kucuk bolumler
                # (100 MB EFI gibi) hicbir zaman gorunmez olmamali.
                widths = [max(MIN_BLOCK, int(strip_w * p.size / total))
                          for p in parts]
                extra = sum(widths) - strip_w
                if extra > 0:
                    flex = [i for i, w in enumerate(widths) if w > MIN_BLOCK]
                    span = sum(widths[i] - MIN_BLOCK for i in flex) or 1
                    for i in flex:
                        widths[i] = max(
                            MIN_BLOCK,
                            widths[i] - int(extra * (widths[i] - MIN_BLOCK) / span))
                x = strip_x
                for part, width in zip(parts, widths):
                    self._blocks.append(
                        (QRect(x, y, max(10, width - 2), ROW_HEIGHT),
                         info.path, part.index))
                    x += width
            y += ROW_HEIGHT + ROW_GAP

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._layout()

    # -- cizim -------------------------------------------------------------
    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.Antialiasing, True)
        if not self._blocks and not self._rows:
            self._layout()
        text_color = palette_color(self, "text")
        dim = palette_color(self, "dim")
        if not self._disks:
            painter.setPen(dim)
            painter.drawText(self.rect(), Qt.AlignCenter,
                             "Fiziksel disk bulunamadi")
            painter.end()
            return

        small = QFont(self.font())
        small.setPointSize(max(7, small.pointSize() - 1))
        bold = QFont(self.font())
        bold.setBold(True)

        for rect, path in self._rows:
            info = next((d for d in self._disks if d.path == path), None)
            if info is None:
                continue
            survey = self._surveys.get(path)
            painter.setPen(QPen(dim, 1))
            painter.setBrush(palette_color(self, "window"))
            painter.drawRoundedRect(rect, 4, 4)
            painter.setPen(text_color)
            painter.setFont(bold)
            painter.drawText(rect.adjusted(8, 6, -6, 0), Qt.AlignLeft | Qt.AlignTop,
                             info.name)
            painter.setFont(small)
            painter.setPen(dim)
            scheme = getattr(survey, "scheme_name", "") or "okunuyor..."
            painter.drawText(rect.adjusted(8, 24, -6, 0),
                             Qt.AlignLeft | Qt.AlignTop, scheme)
            painter.drawText(rect.adjusted(8, 40, -6, 0),
                             Qt.AlignLeft | Qt.AlignTop, human_size(info.size))
            if info.is_system:
                painter.setPen(QColor("#c0392b"))
                painter.drawText(rect.adjusted(8, 54, -6, 0),
                                 Qt.AlignLeft | Qt.AlignTop, "SISTEM DISKI")

            # bolumu olmayan disk: serit yerine aciklama
            if not any(p == path for _r, p, _i in self._blocks):
                strip = QRect(rect.right() + 8, rect.y(),
                              self.width() - rect.right() - 8 - MARGIN,
                              ROW_HEIGHT)
                painter.setPen(QPen(dim, 1, Qt.DashLine))
                painter.setBrush(QColor(FREE_COLOR))
                painter.drawRoundedRect(strip, 4, 4)
                painter.setPen(dim)
                painter.setFont(small)
                note = getattr(survey, "error", "") if survey else ""
                painter.drawText(strip, Qt.AlignCenter,
                                 f"(bolumler okunamadi: {note})" if note
                                 else ("(bolum yok)" if survey
                                       else "(okunuyor...)"))

        for rect, path, index in self._blocks:
            survey = self._surveys.get(path)
            part = next((p for p in getattr(survey, "partitions", [])
                         if p.index == index), None)
            if part is None:
                continue
            base = fs_color(part.fs_type)
            painter.setBrush(base)
            chosen = self._selected == (path, index)
            hovered = self._hover == (path, index)
            painter.setPen(QPen(QColor("#1769c7") if chosen else base.darker(140),
                                2 if chosen else 1))
            painter.drawRoundedRect(rect, 3, 3)
            if hovered and not chosen:
                painter.fillRect(rect.adjusted(2, 2, -2, -2),
                                 QColor(255, 255, 255, 40))
            painter.setPen(QColor("#ffffff"))
            painter.setFont(bold)
            label = part.fs_label or part.name or f"Bolum {part.index}"
            painter.drawText(rect.adjusted(6, 6, -4, 0),
                             Qt.AlignLeft | Qt.AlignTop,
                             _elide(painter, label, rect.width() - 10))
            painter.setFont(small)
            painter.drawText(rect.adjusted(6, 24, -4, 0),
                             Qt.AlignLeft | Qt.AlignTop,
                             _elide(painter, part.fs_type or "ham",
                                    rect.width() - 10))
            painter.drawText(rect.adjusted(6, 40, -4, 0),
                             Qt.AlignLeft | Qt.AlignTop,
                             _elide(painter, human_size(part.size),
                                    rect.width() - 10))
        painter.end()

    # -- etkilesim ---------------------------------------------------------
    def _hit(self, pos) -> Optional[Tuple[str, int]]:
        for rect, path, index in self._blocks:
            if rect.contains(pos):
                return path, index
        for rect, path in self._rows:
            if rect.contains(pos):
                return path, -1
        return None

    def mousePressEvent(self, event):
        hit = self._hit(event.pos())
        if hit is None:
            return
        path, index = hit
        self._selected = hit if index >= 0 else None
        self.update()
        if index >= 0:
            self.partitionSelected.emit(path, index)
        else:
            self.diskSelected.emit(path)

    def mouseDoubleClickEvent(self, event):
        hit = self._hit(event.pos())
        if hit is not None and hit[1] >= 0:
            self.partitionActivated.emit(*hit)

    def mouseMoveEvent(self, event):
        hit = self._hit(event.pos())
        hover = hit if hit and hit[1] >= 0 else None
        if hover != self._hover:
            self._hover = hover
            self.setToolTip(self._tooltip(hover) if hover else "")
            self.update()

    def leaveEvent(self, event):
        self._hover = None
        self.setToolTip("")
        self.update()

    def _tooltip(self, key) -> str:
        path, index = key
        survey = self._surveys.get(path)
        part = next((p for p in getattr(survey, "partitions", [])
                     if p.index == index), None)
        if part is None:
            return ""
        return (f"{path} — Bolum {part.index}\n"
                f"{part.fs_type or 'Bicimlendirilmemis'}"
                + (f" — {part.fs_label}" if part.fs_label else "")
                + f"\n{human_size(part.size)}\nLBA {part.start_lba} - {part.end_lba}"
                "\n\nAcmak icin tiklayin (salt okunur)")


def _elide(painter: QPainter, text: str, width: int) -> str:
    metrics = painter.fontMetrics()
    if metrics.horizontalAdvance(text) <= width:
        return text
    return metrics.elidedText(text, Qt.ElideRight, max(10, width))
