"""Kaynak agacindaki arayuz metinlerini tr(...) ile sarar.

AST konumlarina gore **metinsel** degisiklik yapar: yorumlar, bosluklar ve
satir kirilmalari korunur (ast.unparse kullanilmaz).
"""
from __future__ import annotations

import ast
import io
import re
import sys

WORD = re.compile(r"[A-Za-zçğıöşüÇĞİÖŞÜáéíóúäöüß]{3,}")

# Metnin **herhangi** bir dize argumani cevrilir.
ANY_ARG = {
    "setText", "setToolTip", "setStatusTip", "setWindowTitle", "setTitle",
    "setPlaceholderText", "setHeaderLabel", "setHeaderLabels", "setLabelText",
    "addTab", "setPlainText", "drawText", "emit", "information", "warning",
    "critical", "question", "about", "getText", "getItem",
    "getExistingDirectory", "getOpenFileName", "getSaveFileName",
    "getOpenFileNames", "run_task", "error", "log", "progress", "report",
    "QMessageBox", "InfoDialog", "TextViewDialog", "DeletedFilesDialog",
    "PreviewDialog", "append",
}

# Yalnizca **ilk** dize argumani cevrilir (kalanlar veri anahtaridir).
FIRST_ARG = {
    "addItem", "addAction", "addMenu", "addButton", "addRow", "QAction",
    "QLabel", "QPushButton", "QCheckBox", "QRadioButton", "QGroupBox",
    "QToolBar", "QLineEdit", "QListWidgetItem", "QTableWidgetItem",
    "_set",
}

# Liste argumani iceren cagrilar (liste ogeleri cevrilir).
LIST_ARG = {"setHeaderLabels", "setHorizontalHeaderLabels", "QTreeWidgetItem",
            "addItems"}

SKIP = {"setData", "setProperty", "findData", "setItemData", "get", "startswith",
        "endswith", "join", "split", "replace", "format", "strftime",
        "environ", "getattr", "setattr", "makedirs", "span", "timed"}


def call_name(node: ast.Call) -> str:
    func = node.func
    if isinstance(func, ast.Attribute):
        return func.attr
    if isinstance(func, ast.Name):
        return func.id
    return ""


def has_words(text: str) -> bool:
    return bool(WORD.search(text))


def py_literal(text: str) -> str:
    out = text.replace("\\", "\\\\").replace('"', '\\"')
    out = out.replace("\n", "\\n").replace("\t", "\\t").replace("\r", "\\r")
    return '"' + out + '"'


class Wrapper:
    def __init__(self, source: str):
        self.text = source
        self.data = source.encode("utf-8")
        self.line_start = [0]
        for line in self.data.split(b"\n")[:-1]:
            self.line_start.append(self.line_start[-1] + len(line) + 1)
        self.edits = []          # (start, end, yeni metin)
        self.strings = []        # cevrilen kaynak metinler

    def span(self, node) -> tuple:
        start = self.line_start[node.lineno - 1] + node.col_offset
        end = self.line_start[node.end_lineno - 1] + node.end_col_offset
        return start, end

    def src(self, node) -> str:
        start, end = self.span(node)
        return self.data[start:end].decode("utf-8")

    # -- tek dugum -------------------------------------------------------
    def wrap_constant(self, node: ast.Constant) -> bool:
        if not isinstance(node.value, str) or not has_words(node.value):
            return False
        start, end = self.span(node)
        self.edits.append((start, end, "tr(" + self.src(node) + ")"))
        self.strings.append(node.value)
        return True

    def wrap_fstring(self, node: ast.JoinedStr) -> bool:
        parts = []
        args = []
        plain = []
        for value in node.values:
            if isinstance(value, ast.Constant) and isinstance(value.value, str):
                plain.append(value.value)
                parts.append(value.value.replace("{", "{{").replace("}", "}}"))
                continue
            if not isinstance(value, ast.FormattedValue):
                return False
            spec = ""
            if value.format_spec is not None:
                if not isinstance(value.format_spec, ast.JoinedStr):
                    return False
                for piece in value.format_spec.values:
                    if not (isinstance(piece, ast.Constant)
                            and isinstance(piece.value, str)):
                        return False        # ic ice yer tutuculu bicim: atla
                    spec += piece.value
            conversion = ""
            if value.conversion != -1:
                conversion = "!" + chr(value.conversion)
            parts.append("{" + conversion + (":" + spec if spec else "") + "}")
            args.append(self.src(value.value))
        template = "".join(parts)
        if not has_words("".join(plain)):
            return False
        start, end = self.span(node)
        new = "tr(" + py_literal(template)
        if args:
            new += ", " + ", ".join(args)
        new += ")"
        self.edits.append((start, end, new))
        self.strings.append(template)
        return True

    def wrap(self, node) -> bool:
        if isinstance(node, ast.Constant):
            return self.wrap_constant(node)
        if isinstance(node, ast.JoinedStr):
            return self.wrap_fstring(node)
        return False

    def is_text(self, node) -> bool:
        if isinstance(node, ast.Constant):
            return isinstance(node.value, str)
        return isinstance(node, ast.JoinedStr)

    # -- gezinme ---------------------------------------------------------
    def run(self, tree) -> None:
        for node in ast.walk(tree):
            if not isinstance(node, ast.Call):
                continue
            name = call_name(node)
            if not name or name in SKIP:
                continue
            if name in LIST_ARG:
                for arg in node.args:
                    if isinstance(arg, (ast.List, ast.Tuple)):
                        for element in arg.elts:
                            if self.is_text(element):
                                self.wrap(element)
            if name in ANY_ARG:
                for arg in node.args:
                    if self.is_text(arg):
                        self.wrap(arg)
                for kw in node.keywords:
                    if kw.arg in ("note", "title", "text", "label") \
                            and self.is_text(kw.value):
                        self.wrap(kw.value)
            elif name in FIRST_ARG:
                for arg in node.args:
                    if self.is_text(arg):
                        self.wrap(arg)
                        break

    def raises(self, tree) -> None:
        """raise XError("...") mesajlarini sarar."""
        for node in ast.walk(tree):
            if not isinstance(node, ast.Raise) or node.exc is None:
                continue
            exc = node.exc
            if not isinstance(exc, ast.Call) or not exc.args:
                continue
            if self.is_text(exc.args[0]):
                self.wrap(exc.args[0])

    def apply(self) -> str:
        seen = set()
        edits = []
        for start, end, new in self.edits:
            if start in seen:
                continue
            seen.add(start)
            edits.append((start, end, new))
        edits.sort(key=lambda e: e[0], reverse=True)
        data = self.data
        for start, end, new in edits:
            data = data[:start] + new.encode("utf-8") + data[end:]
        return data.decode("utf-8")


def import_line(path: str) -> str:
    depth = path.replace("\\", "/").split("src/diskultimate/")[1].count("/")
    return "from " + "." * (depth + 1) + "i18n import tr"


def add_import(source: str, line: str) -> str:
    if line in source:
        return source
    tree = ast.parse(source)
    last = 0
    for node in tree.body:
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            last = node.end_lineno
    lines = source.split("\n")
    lines.insert(last, line)
    return "\n".join(lines)


def process(path: str, do_raises: bool = False, only_raises: bool = False):
    source = io.open(path, encoding="utf-8").read()
    tree = ast.parse(source)
    wrapper = Wrapper(source)
    if not only_raises:
        wrapper.run(tree)
    if do_raises or only_raises:
        wrapper.raises(tree)
    if not wrapper.edits:
        return 0, []
    new = wrapper.apply()
    new = add_import(new, import_line(path))
    ast.parse(new)          # sozdizimi denetimi
    io.open(path, "w", encoding="utf-8", newline="\n").write(new)
    return len(wrapper.edits), wrapper.strings


if __name__ == "__main__":
    total = 0
    for target in sys.argv[1:]:
        flag_raises = target.startswith("+raises:")
        flag_only = target.startswith("only:")
        name = target.split(":", 1)[1] if (flag_raises or flag_only) else target
        count, _ = process(name, do_raises=flag_raises, only_raises=flag_only)
        print(f"{count:4d}  {name}")
        total += count
    print("toplam", total)

