                txt = "".join(x.value for x in c.values if isinstance(x, ast.Constant))
                if WORD.search(txt):
                    hits.append((node.lineno, txt[:50]))
            elif isinstance(c, ast.IfExp):
                for sub in (c.body, c.orelse):
                    if isinstance(sub, ast.Constant) and isinstance(sub.value, str) and WORD.search(sub.value):
                        hits.append((node.lineno, sub.value[:50]))
    if hits:
        print(f"{p.name}: {len(hits)}")
