"""Kaynak metinleri kisa karma (hash) ile listeler / ceviri birlestirir."""
import hashlib
import io
import json
import sys

CAT = "src/diskultimate/i18n/catalogs/{}.json"


def digest(text: str) -> str:
    return hashlib.sha1(text.encode("utf-8")).hexdigest()[:6]


def load(code):
    return json.load(io.open(CAT.format(code), encoding="utf-8"))


def dump(code, start, end, only_missing=True):
    data = load(code)
    keys = sorted(k for k in data if not data[k]) if only_missing else sorted(data)
    for key in keys[start:end]:
        shown = key.replace("\n", "\\n")
        print(f"{digest(key)}\t{shown}")
    print(f"--- {len(keys)} eksik, {start}..{min(end, len(keys))} gosterildi")


def merge(code, path):
    data = load(code)
    by_hash = {digest(k): k for k in data}
    new = json.load(io.open(path, encoding="utf-8"))
    unknown, applied = [], 0
    for key, value in new.items():
        source = by_hash.get(key)
        if source is None:
            unknown.append(key)
            continue
        data[source] = value
        applied += 1
    with io.open(CAT.format(code), "w", encoding="utf-8", newline="\n") as fh:
        json.dump(data, fh, ensure_ascii=False, indent=2, sort_keys=True)
        fh.write("\n")
    missing = sum(1 for v in data.values() if not v)
    print(f"{applied} ceviri islendi, {len(unknown)} bilinmeyen karma, "
          f"{missing} giris hala bos")
    for u in unknown[:10]:
        print("  bilinmeyen:", u)


if __name__ == "__main__":
    if sys.argv[1] == "dump":
        dump(sys.argv[2], int(sys.argv[3]), int(sys.argv[4]))
    else:
        merge(sys.argv[2], sys.argv[3])

