input.content:
"""Gettext `.po` dosyalarini okuyup yazar — saf Python, harici arac yok.

## Neden `.po`

Ceviri sozlugu once duz JSON'du. `.po` bicimi ayni seyi tasir ama uc sey
fazladan getirir (ADR 0027 eki, `.claude/docs/i18n-raporu.md` bolum 12):

1. **Cogul ekleri** — `Plural-Forms` basligi dil basina kurali tasir; kurali
   Python'un kendi `gettext.c2py()` islevi derler (standart kutuphane).
2. **Baglam** (`msgctxt`) — ayni kaynak metin iki yerde farkli cevrilebilir.
3. **Bayat ceviri kaybolmaz** — kaynak metin degisince ceviri silinmez,
   `#, fuzzy` isaretlenip onerilmeye devam eder (`merge`).

Ustelik Poedit / Weblate / Crowdin bu bicimi dogrudan okur; ceviri icin kod
bilgisi gerekmez.

## Neden gettext calisma zamani degil

`gettext` modulu yalnizca **derlenmis** `.mo` okur; derlemek icin `msgfmt`
gerekir. `.mo` yalnizca bir hiz optimizasyonudur: 1315 girisli bir `.po`
dosyasi burada ~1 ms'de okunuyor (olcum: `.claude/docs/i18n-raporu.md`).
Bu yuzden `.po` dogrudan okunur; derleme adimi yoktur.

## Desteklenen alt kume

`msgctxt`, `msgid`, `msgid_plural`, `msgstr`, `msgstr[n]`, `#, fuzzy`,
yorumlar (`#`, `#.`, `#:`), cok satirli dizeler ve `#~` ile bayatlatilmis
girisler. Desteklenmeyen tek sey `#| ` (onceki msgid) satirlaridir; okunur
ama saklanmaz.
"""
from __future__ import annotations

import difflib
import re
from typing import Dict, List, Optional, Tuple

# Bir girisin kimligi: (baglam, kaynak metin). Baglamsiz girislerde baglam None.
Key = Tuple[Optional[str], str]

_ESCAPES = {"\\": "\\\\", '"': '\\"', "\n": "\\n", "\t": "\\t", "\r": "\\r"}
_UNESCAPES = {"n": "\n", "t": "\t", "r": "\r", '"': '"', "\\": "\\"}

_LINE = re.compile(r'^\s*(msgctxt|msgid_plural|msgid|msgstr(?:\[(\d+)\])?)\s+"(.*)"\s*$')
_CONT = re.compile(r'^\s*"(.*)"\s*$')


def escape(text: str) -> str:
    return "".join(_ESCAPES.get(ch, ch) for ch in text)


def unescape(text: str) -> str:
    out = []
    index = 0
    while index < len(text):
        ch = text[index]
        if ch == "\\" and index + 1 < len(text):
            out.append(_UNESCAPES.get(text[index + 1], text[index + 1]))
            index += 2
        else:
            out.append(ch)
            index += 1
    return "".join(out)


class Entry:
    """Tek bir ceviri girisi."""

    def __init__(self, msgid: str, msgstr: str = "",
                 context: Optional[str] = None,
                 plural: Optional[str] = None,
                 plurals: Optional[List[str]] = None,
                 comments: Optional[List[str]] = None,
                 references: Optional[List[str]] = None,
                 fuzzy: bool = False, obsolete: bool = False):
        self.msgid = msgid
        self.msgstr = msgstr
        self.context = context
        self.plural = plural                    # msgid_plural
        self.plurals = plurals or []            # msgstr[0], msgstr[1], ...
        self.comments = comments or []          # "#." ile yazilan aciklamalar
        self.references = references or []      # "#:" kaynak konumlari
        self.fuzzy = fuzzy
        self.obsolete = obsolete

    @property
    def key(self) -> Key:
        return (self.context, self.msgid)

    @property
    def translated(self) -> bool:
        """Kullanilabilir bir cevirisi var mi? (fuzzy **sayilmaz**)"""
        if self.fuzzy or self.obsolete:
            return False
        if self.plural is not None:
            return any(self.plurals)
        return bool(self.msgstr)

    def __repr__(self) -> str:
        return f"<Entry {self.msgid[:30]!r} fuzzy={self.fuzzy}>"


class Catalog:
    """Bir `.po` dosyasinin tamami: basligi ve girisleri."""

    def __init__(self, entries: Optional[List[Entry]] = None,
                 headers: Optional[Dict[str, str]] = None):
        self.entries: List[Entry] = entries or []
        self.headers: Dict[str, str] = headers or {}

    # -- arama ------------------------------------------------------------
    def by_key(self) -> Dict[Key, Entry]:
        return {e.key: e for e in self.entries if not e.obsolete}

    @property
    def plural_forms(self) -> str:
        return self.headers.get("Plural-Forms", "")

    # -- sayim ------------------------------------------------------------
    def counts(self) -> Dict[str, int]:
        canli = [e for e in self.entries if not e.obsolete]
        return {
            "toplam": len(canli),
            "cevrili": sum(1 for e in canli if e.translated),
            "fuzzy": sum(1 for e in canli if e.fuzzy),
            "bos": sum(1 for e in canli if not e.translated and not e.fuzzy),
            "bayat": sum(1 for e in self.entries if e.obsolete),
        }


# --------------------------------------------------------------------------
# Okuma
# --------------------------------------------------------------------------
def parse(text: str) -> Catalog:
    """`.po` metnini `Catalog` nesnesine cevirir."""
    catalog = Catalog()
    entry = Entry("")
    alan: Optional[str] = None          # su an hangi dizeye ekliyoruz
    index = 0                           # msgstr[index]
    baslangic = True                    # henuz hicbir alan gorulmedi

    def bitir():
        nonlocal entry, alan, baslangic
        if not baslangic:
            if entry.msgid == "" and entry.context is None and not entry.obsolete:
                catalog.headers.update(_parse_headers(entry.msgstr))
            else:
                catalog.entries.append(entry)
        entry = Entry("")
        alan = None
        baslangic = True

    for ham in text.split("\n"):
        satir = ham.rstrip("\r")
        if not satir.strip():
            bitir()
            continue
        bayat = satir.lstrip().startswith("#~")
        if bayat:
            satir = satir.lstrip()[2:].lstrip()
        elif satir.lstrip().startswith("#"):
            yorum = satir.lstrip()
            if not baslangic:               # yeni girisin yorumlari basladi
                bitir()
            if yorum.startswith("#,"):
                entry.fuzzy = "fuzzy" in yorum
            elif yorum.startswith("#:"):
                entry.references.append(yorum[2:].strip())
            elif yorum.startswith("#."):
                entry.comments.append(yorum[2:].strip())
            continue

        eslesme = _LINE.match(satir)
        if eslesme:
            ad, cogul_no, deger = eslesme.group(1), eslesme.group(2), eslesme.group(3)
            if ad == "msgid" and not baslangic and alan != "msgctxt":
                bitir()                      # onceki giris bitti
            baslangic = False
            entry.obsolete = entry.obsolete or bayat
            deger = unescape(deger)
            if ad == "msgctxt":
                entry.context = deger
                alan = "msgctxt"
            elif ad == "msgid":
                entry.msgid = deger
                alan = "msgid"
            elif ad == "msgid_plural":
                entry.plural = deger
                alan = "plural"
            elif cogul_no is not None:
                index = int(cogul_no)
                while len(entry.plurals) <= index:
                    entry.plurals.append("")
                entry.plurals[index] = deger
                alan = "plurals"
            else:
                entry.msgstr = deger
                alan = "msgstr"
            continue

        devam = _CONT.match(satir)
        if devam and alan:
            deger = unescape(devam.group(1))
            if alan == "msgctxt":
                entry.context = (entry.context or "") + deger
            elif alan == "msgid":
                entry.msgid += deger
            elif alan == "plural":
                entry.plural = (entry.plural or "") + deger
            elif alan == "plurals":
                entry.plurals[index] += deger
            else:
                entry.msgstr += deger
    bitir()
    return catalog


def _parse_headers(text: str) -> Dict[str, str]:
    headers = {}
