def parse(text: str) -> Catalog:
    """`.po` metnini `Catalog` nesnesine cevirir."""
    catalog = Catalog()
    entry = Entry("")
    alan: Optional[str] = None          # su an hangi dizeye ekliyoruz
    index = 0                           # msgstr[index]
    baslangic = True                    # henuz hicbir alan gorulmedi

    def bitir():
        nonlocal entry, alan, baslangic
        if not baslangic:
            if entry.msgid == "" and entry.context is None and not entry.obsolete:
                catalog.headers.update(_parse_headers(entry.msgstr))
            else:
                catalog.entries.append(entry)
        entry = Entry("")
        alan = None
        baslangic = True

    for ham in text.split("\n"):
        satir = ham.rstrip("\r")
        if not satir.strip():
            bitir()
            continue
        bayat = satir.lstrip().startswith("#~")
        if bayat:
            satir = satir.lstrip()[2:].lstrip()
        elif satir.lstrip().startswith("#"):
            yorum = satir.lstrip()
            if not baslangic:               # yeni girisin yorumlari basladi
                bitir()
            if yorum.startswith("#,"):
                entry.fuzzy = "fuzzy" in yorum
            elif yorum.startswith("#:"):
                entry.references.append(yorum[2:].strip())
            elif yorum.startswith("#."):
                entry.comments.append(yorum[2:].strip())
            continue

        eslesme = _LINE.match(satir)
        if eslesme:
            ad, cogul_no, deger = eslesme.group(1), eslesme.group(2), eslesme.group(3)
            if ad == "msgid" and not baslangic and alan != "msgctxt":
                bitir()                      # onceki giris bitti
            baslangic = False
            entry.obsolete = entry.obsolete or bayat
            deger = unescape(deger)
            if ad == "msgctxt":
                entry.context = deger
                alan = "msgctxt"
            elif ad == "msgid":
                entry.msgid = deger
                alan = "msgid"
            elif ad == "msgid_plural":
                entry.plural = deger
                alan = "plural"
            elif cogul_no is not None:
                index = int(cogul_no)
                while len(entry.plurals) <= index:
                    entry.plurals.append("")
                entry.plurals[index] = deger
                alan = "plurals"
            else:
                entry.msgstr = deger
                alan = "msgstr"
            continue

        devam = _CONT.match(satir)
        if devam and alan:
            deger = unescape(devam.group(1))
            if alan == "msgctxt":
                entry.context = (entry.context or "") + deger
            elif alan == "msgid":
                entry.msgid += deger
            elif alan == "plural":
                entry.plural = (entry.plural or "") + deger
            elif alan == "plurals":
                entry.plurals[index] += deger
            else:
                entry.msgstr += deger
    bitir()
    return catalog


def _parse_headers(text: str) -> Dict[str, str]:
    headers = {}
    for satir in text.split("\n"):
        if ":" in satir:
            ad, _, deger = satir.partition(":")
            headers[ad.strip()] = deger.strip()
    return headers


# --------------------------------------------------------------------------
# Yazma
# --------------------------------------------------------------------------
def _dump_string(ad: str, deger: str, sarma: int = 74) -> List[str]:
    """`msgid "..."` satirini (gerekirse cok satirli) uretir."""
    kacisli = escape(deger)
    if len(kacisli) + len(ad) + 4 <= sarma and "\\n" not in kacisli:
        return [f'{ad} "{kacisli}"']
    satirlar = [f'{ad} ""']
    # Satir sonlarindan sonra bol; kalan uzun parcalari bosluktan sar.
    parcalar = deger.split("\n")
    for i, parca in enumerate(parcalar):
        metin = parca + ("\n" if i < len(parcalar) - 1 else "")
        if not metin:
            continue
        for kucuk in _wrap(metin, sarma):
            satirlar.append(f'"{escape(kucuk)}"')
    if len(satirlar) == 1:
        satirlar.append('""')
    return satirlar


def _wrap(text: str, width: int) -> List[str]:
    out: List[str] = []
    current = ""
    for word in text.split(" "):
        aday = word if not current else current + " " + word
        if len(escape(aday)) > width and current:
            out.append(current + " ")
            current = word
        else:
            current = aday
    if current:
        out.append(current)
    return out


def dump(catalog: Catalog) -> str:
    """`Catalog` nesnesini `.po` metnine cevirir."""
    out: List[str] = []
    basliklar = "".join(f"{ad}: {deger}\\n" for ad, deger in catalog.headers.items())
    out.append('msgid ""')
    out.append('msgstr ""')
    for ad, deger in catalog.headers.items():
        out.append(f'"{ad}: {escape(deger)}\\n"')
    out.append("")
    for entry in catalog.entries:
        onek = "#~ " if entry.obsolete else ""
        for yorum in entry.comments:
            out.append(f"#. {yorum}")
        for kaynak in entry.references:
            out.append(f"#: {kaynak}")
        if entry.fuzzy:
            out.append("#, fuzzy")
        if entry.context is not None:
            out += [onek + s for s in _dump_string("msgctxt", entry.context)]
        out += [onek + s for s in _dump_string("msgid", entry.msgid)]
        if entry.plural is not None:
            out += [onek + s for s in _dump_string("msgid_plural", entry.plural)]
            for i, deger in enumerate(entry.plurals or ["", ""]):
                out += [onek + s for s in _dump_string(f"msgstr[{i}]", deger)]
        else:
            out += [onek + s for s in _dump_string("msgstr", entry.msgstr)]
        out.append("")
    return "\n".join(out)


# --------------------------------------------------------------------------
# Birlestirme (msgmerge esdegeri)
# --------------------------------------------------------------------------
def merge(mevcut: Catalog, kaynak: List[Entry], benzerlik: float = 0.8) -> dict:
    """Kaynaktaki metinleri mevcut sozluge isler.

    - Ayni `msgid` varsa cevirisi **korunur**.
    - Kaynakta artik olmayan giris silinmez, **bayatlatilir** (`#~`).
    - Yeni bir giris, bayatlayan bir girise yeterince benziyorsa cevirisi
      tasinip `#, fuzzy` isaretlenir — `msgmerge`'in yaptigi budur. Kaynak
      metindeki bir yazim duzeltmesi boylece cevirileri dusurmez.

    Sonuc sayaclarini dondurur.
    """
    eski = {e.key: e for e in mevcut.entries if not e.obsolete}
    bayatlar = [e for e in mevcut.entries if e.obsolete]
    yeni_liste: List[Entry] = []
    sayac = {"korunan": 0, "yeni": 0, "fuzzy": 0, "bayatlayan": 0}

    kullanilan = set()
    for taze in kaynak:
        onceki = eski.get(taze.key)
        if onceki is not None:
            kullanilan.add(taze.key)
            onceki.comments = taze.comments
            onceki.references = taze.references
            onceki.plural = taze.plural
            if taze.plural is not None and not onceki.plurals:
                onceki.plurals = ["", ""]
            yeni_liste.append(onceki)
            sayac["korunan"] += 1
        else:
            yeni_liste.append(taze)
            sayac["yeni"] += 1

    # Kaynakta kalmayanlar bayatlar; benzer yeni girise ceviri tasinir.
    dusenler = [e for key, e in eski.items() if key not in kullanilan]
    bos_yeniler = [e for e in yeni_liste if not e.translated and not e.plural]
    for dusen in dusenler:
        if dusen.translated:
            aday = difflib.get_close_matches(
                dusen.msgid, [e.msgid for e in bos_yeniler], n=1, cutoff=benzerlik)
            if aday:
                hedef = next(e for e in bos_yeniler if e.msgid == aday[0])
                hedef.msgstr = dusen.msgstr
                hedef.fuzzy = True
                bos_yeniler.remove(hedef)
                sayac["fuzzy"] += 1
        dusen.obsolete = True
        dusen.fuzzy = False
        bayatlar.append(dusen)
        sayac["bayatlayan"] += 1

    # Ayni msgid bayat listede yeniden belirdiyse bayat kopyasi gereksizdir.
    canli = {e.key for e in yeni_liste}
    bayatlar = [e for e in bayatlar if e.key not in canli]

    mevcut.entries = yeni_liste + bayatlar
    return sayac

